{
  "operation": "meta_get_semantics",
  "source": "metadata",
  "parameters": {},
  "currency": "n/a",
  "row_count": 1,
  "rows": [
    {
      "systems": {
        "erp": {
          "description": "Finance / ERP export (e-conomic-like). Sales invoices with lines, customer and product masters, chart of accounts and cost ledger entries. Base currency DKK.",
          "tables": {
            "customers": {
              "key": "customer_number",
              "fields": {
                "customer_number": "ERP customer id (5 digits)",
                "name": "legal name",
                "customer_group_number/_name": "customer group (one per market)",
                "country": "country in Danish (Danmark/Sverige/Tyskland) -> market via value_mappings",
                "currency": "invoicing currency",
                "vat_number": "optional",
                "created_date": "customer created in ERP",
                "barred": "blocked for invoicing"
              }
            },
            "products": {
              "key": "product_number",
              "fields": {
                "product_group_number": "10/20/30 -> product category via value_mappings",
                "sales_price_dkk": "list price DKK",
                "cost_price_dkk": "standard cost DKK"
              }
            },
            "invoices": {
              "key": "invoice_number",
              "fields": {
                "invoice_date": "revenue date",
                "currency": "invoice currency (DKK/SEK/EUR)",
                "exchange_rate": "DKK per 1 unit of invoice currency, fixed per invoice",
                "net_amount": "net of VAT, invoice currency",
                "net_amount_dkk": "net_amount * exchange_rate",
                "document_type": "invoice | credit_note (credit notes carry negative amounts)",
                "credited_invoice_number": "for credit notes: the invoice being credited"
              }
            },
            "invoice_lines": {
              "key": "invoice_number + line_number",
              "fields": {
                "unit_price": "invoice currency, before discount",
                "discount_pct": "line discount in percent",
                "net_amount": "quantity * unit_price * (1 - discount), invoice currency",
                "unit_cost_dkk/total_cost_dkk": "cost of sales in DKK (materials, parts, subcontractors; technician salaries are payroll, not cost of sales)"
              }
            },
            "accounts": {
              "key": "account_number",
              "fields": {
                "type": "revenue | cost of sales | personnel | opex"
              }
            },
            "ledger_entries": {
              "key": "entry_number",
              "fields": {
                "date": "posting date",
                "amount_dkk": "positive = cost",
                "department": "DK/SE/DE, sometimes blank",
                "text": "posting text"
              },
              "note": "Contains cost postings not generated by sales invoices: the monthly payroll journal (company totals, no department split) and operating expenses. Revenue and cost of sales are derived from invoices, not from the ledger."
            },
            "exchange_rates": {
              "key": "month + currency",
              "fields": {
                "rate_to_dkk": "monthly reference rate"
              }
            }
          }
        },
        "crm": {
          "description": "CRM export (HubSpot-like): users (owners), companies, deals, activities and a property change history. Contains pipeline history from September 2024.",
          "tables": {
            "owners": {
              "key": "user_id",
              "fields": {
                "user_id": "usr_######",
                "team": "sales team label",
                "active/archived_at": "archived users keep ownership of old records"
              }
            },
            "companies": {
              "key": "company_id",
              "fields": {
                "company_id": "cmp_#####",
                "name": "as typed by sales (may differ from ERP legal name)",
                "country": "English country name, sometimes blank",
                "lifecycle_stage": "subscriber | lead | opportunity | customer",
                "owner_id": "CURRENT owner (see property_history for changes)"
              }
            },
            "deals": {
              "key": "deal_id",
              "fields": {
                "created_at": "deal created (pipeline date)",
                "closed_at": "actual close (blank while open)",
                "expected_close_date": "forecast close for open deals; may lie in the past (slipped)",
                "stage": "see crm_stages",
                "outcome": "won | lost | open",
                "deal_type": "New Business | Existing Business | Renewal",
                "amount/deal_currency": "deal value in deal currency",
                "amount_company_currency": "deal value converted to DKK by the CRM",
                "discount_pct": "optional",
                "loss_reason": "optional free choice, often blank",
                "market": "English country name, sometimes blank (see market fallback)",
                "product_category": "CRM label, sometimes blank"
              }
            },
            "activities": {
              "key": "activity_id",
              "fields": {
                "timestamp": "when logged",
                "type": "CALL | EMAIL | MEETING | NOTE",
                "deal_id": "optional",
                "body": "notes text, optional"
              }
            },
            "property_history": {
              "key": "object_id + changed_at",
              "fields": {
                "property": "hubspot_owner_id (owner changes) or lifecyclestage",
                "value_before/value_after": "user ids for owner changes",
                "source": "CRM_UI | BULK_ASSIGN | WORKFLOW | IMPORT"
              }
            }
          }
        },
        "payroll": {
          "description": "Group payroll export (Danløn-like), all countries, monthly pay slips in local currency.",
          "tables": {
            "employees": {
              "key": "employee_id",
              "fields": {
                "employee_id": "country prefix + 4 digits",
                "department": "organisational department",
                "job_title": "CURRENT title",
                "employment_start/end": "inclusive; end blank = still employed",
                "status": "active | terminated",
                "current_base_salary": "latest monthly base, local currency",
                "work_email": "optional"
              }
            },
            "payroll_entries": {
              "key": "pay_period + employee_id",
              "fields": {
                "pay_period": "YYYY-MM",
                "base_salary": "prorated for partial months, local currency",
                "commission/bonus/overtime_pay": "variable pay, local currency",
                "gross_pay": "sum of pay elements",
                "pension_employer/social_contributions_employer": "employer costs, local currency",
                "employer_cost": "gross_pay + employer pension + employer social contributions",
                "fx_rate_to_dkk": "rate used by payroll for DKK reporting",
                "employer_cost_dkk": "employer_cost * fx_rate_to_dkk"
              }
            }
          }
        },
        "mappings": {
          "description": "Cross-system identity and value mappings maintained by the business (not by any source system).",
          "tables": {
            "crm_company_erp_customer": {
              "fields": {
                "match_method": "exact_name | vat_number | name_contains | manual",
                "note": "e.g. duplicate CRM record"
              },
              "note": "Many-to-one possible (duplicate CRM records). Not every customer is mapped."
            },
            "employee_crm_user": {
              "fields": {
                "match_basis": "how the link was established",
                "note": "name differences etc."
              },
              "note": "Some CRM users have no payroll record (former staff, system users)."
            },
            "value_mappings": {
              "note": "Canonical market and product category per system label."
            }
          }
        }
      },
      "currencies": {
        "canonical": "DKK. All aggregated money values returned by the runtime are DKK.",
        "erp": "revenue_dkk = invoice_lines.net_amount * invoices.exchange_rate; costs are already DKK.",
        "crm": "value_dkk = deals.amount_company_currency (the CRM's own DKK conversion).",
        "payroll": "*_dkk = local amount * payroll_entries.fx_rate_to_dkk (employer_cost_dkk as exported).",
        "note": "Each system converts with its own rates; values from different systems can differ slightly. Source-currency amounts are kept on record-level results."
      },
      "dates": {
        "erp_revenue": "invoice_date (credit notes on their own date)",
        "erp_costs": "ledger_entries.date",
        "crm_pipeline_created": "deals.created_at",
        "crm_closed": "deals.closed_at (win rate, won/lost value)",
        "crm_open_at_date": "created_at <= date and (closed_at blank or closed_at > date); stage at a past date is not recorded",
        "payroll": "pay_period month; employment_start/end inclusive",
        "periods": "all period boundaries inclusive"
      },
      "markets": {
        "codes": {
          "DK": "Denmark",
          "SE": "Sweden",
          "DE": "Germany"
        },
        "erp": "customers.country (Danish name) -> market",
        "crm_companies": "companies.country (English name) -> market; blank -> unknown",
        "crm_deals_fallback": "deals.market -> else companies.country of the deal's company -> else deals.deal_currency (each market trades in its own currency: DKK=DK, SEK=SE, EUR=DE). Results report market_source for transparency.",
        "payroll": "employees.country (ISO code)",
        "erp_ledger": "ledger_entries.department where present; payroll journal has no department"
      },
      "product_categories": {
        "canonical": [
          "Equipment",
          "Components",
          "Service"
        ],
        "erp": "products.product_group_number: 10 Equipment (pumps and systems), 20 Components (spare parts), 30 Service (service agreements, technician hours, commissioning)",
        "crm": "deals.product_category: Pumps & Systems / Spare Parts Agreement / Service Contract; blank -> null"
      },
      "crm_stages": {
        "open": [
          "Qualification",
          "Needs Analysis",
          "Proposal Sent",
          "Negotiation"
        ],
        "closed": [
          "Closed Won",
          "Closed Lost"
        ],
        "pipelines": {
          "Nordics Sales": "DK/SE new sales",
          "DACH Sales": "DE new sales",
          "Service Renewals": "renewal deals"
        },
        "deal_types": {
          "New Business": "company not yet a customer",
          "Existing Business": "existing customer",
          "Renewal": "renewal of a service contract"
        }
      },
      "metrics": {
        "revenue": "sum of invoice line net amounts in DKK incl. credit notes, by invoice_date",
        "cost_of_sales": "sum of invoice_lines.total_cost_dkk",
        "gross_profit": "revenue - cost_of_sales; gross_margin = gross_profit / revenue",
        "personnel_costs_erp": "ledger accounts of type personnel (monthly payroll journal)",
        "other_operating_costs": "ledger accounts of type opex",
        "operating_profit": "revenue - cost_of_sales - personnel costs - other operating costs; operating_margin = operating_profit / revenue",
        "avg_discount_pct": "1 - revenue / list value (quantity * unit_price before discount)",
        "pipeline_created": "count and DKK value of deals with created_at in the period",
        "win_rate": "won / (won + lost) by count for deals with closed_at in the period; value_win_rate uses DKK value",
        "renewals": "deals with deal_type Renewal; excluded from pipeline and win rate unless include_renewals=true",
        "headcount_point_in_time": "employees whose employment_start <= date <= employment_end (or no end)",
        "headcount_average_monthly": "average number of employees with a payroll entry per month in the period",
        "personnel_costs_payroll": "sum of employer_cost_dkk by pay_period",
        "base_salary_change": "like-for-like: employees employed the whole of both months; change in LOCAL currency (excludes FX), aggregated with from-month DKK weights"
      },
      "data_quality": [
        "Names differ between systems (legal names in ERP, typed names in CRM, spelling variants for people).",
        "Optional fields are often blank: loss_reason, industry, country, market, product_category, VAT number, work email, ledger department.",
        "Duplicate CRM company records exist; the mapping links both to one ERP customer.",
        "Some ERP customers are not in the CRM, and a few existing ones are not mapped.",
        "Archived CRM users can still own old records.",
        "Open deals may have expected_close_date in the past.",
        "Date coverage differs slightly between systems (see meta_describe_sources); the CRM holds pipeline history before the ERP/payroll period and its extract can include records a day past their cut-off."
      ]
    }
  ]
}

